<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/pengawasan') ?>">← Daftar pemeriksaan</a></div>
<section class="form-panel"><div class="form-intro"><span class="panel-overline">RENCANA PENGAWASAN</span><h2>Identitas pemeriksaan</h2><p>Nomor tugas dan petugas dapat dilengkapi saat penugasan.</p></div><form method="post" action="<?= site_url('admin/pengawasan/simpan') ?>"><?= csrf_input() ?><input type="hidden" name="id" value="<?= h($row['id']??'') ?>"><div class="form-grid"><label class="form-full">Koperasi <span class="required">*</span><select id="inspection-cooperative" name="cooperative_id" required><option value="">Pilih koperasi wilayah Rembang</option><?php foreach ($cooperatives as $c): ?><option value="<?= $c['id'] ?>" <?= (string)($row['cooperative_id']??'')===(string)$c['id']?'selected':'' ?>><?= h($c['name'].' · '.$c['nik']) ?></option><?php endforeach; ?></select></label><label>Jenis pemeriksaan<select name="inspection_type"><option value="routine" <?= ($row['inspection_type']??'routine')==='routine'?'selected':'' ?>>Rutin</option><option value="insidental" <?= ($row['inspection_type']??'')==='insidental'?'selected':'' ?>>Insidental</option></select></label><label>Tanggal mulai<input type="date" name="started_on" value="<?= h($row['started_on']??'') ?>"></label><label>Nomor surat tugas<input type="text" name="assignment_number" maxlength="120" value="<?= h($row['assignment_number']??'') ?>" placeholder="Jika sudah tersedia"></label><label>Petugas penanggung jawab<select name="lead_user_id"><option value="">Belum ditetapkan</option><?php foreach ($staff as $s): ?><option value="<?= $s['id'] ?>" <?= (string)($row['lead_user_id']??'')===(string)$s['id']?'selected':'' ?>><?= h($s['full_name']) ?></option><?php endforeach; ?></select></label><label class="form-full">Penilaian kesehatan terkait<select id="inspection-assessment" name="assessment_id"><option value="">Tanpa penilaian terkait</option><?php foreach ($assessments as $a): ?><option data-cooperative="<?= $a['cooperative_id'] ?>" value="<?= $a['id'] ?>" <?= (string)($row['assessment_id']??'')===(string)$a['id']?'selected':'' ?>><?= h($a['cooperative_name']) ?> · tahun <?= h($a['fiscal_year']) ?> · revisi <?= h($a['revision_no']) ?></option><?php endforeach; ?></select><small>Daftar mengikuti koperasi yang dipilih dan hanya memuat penilaian terkunci.</small></label></div><div class="form-actions"><button class="button button-dark">Simpan pemeriksaan →</button></div></form></section>

<script>(function(){const c=document.getElementById("inspection-cooperative"),a=document.getElementById("inspection-assessment");function sync(){const current=a.value;for(const o of a.options){if(!o.value)continue;o.hidden=o.dataset.cooperative!==c.value}if(a.selectedOptions[0] && a.selectedOptions[0].hidden)a.value="";else a.value=current}c.addEventListener("change",sync);sync()})()</script>
